import React, { useState } from 'react';
import axios from 'axios';
import './ClienteManagement.css'; // Certifique-se de que o caminho para o CSS está correto

const App = () => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [telefone, setTelefone] = useState('');

  // Função para criar um cliente
  const handleCreateCliente = async (e) => {
    e.preventDefault();
    try {
      const cliente = { nome, email, telefone };
      const response = await axios.post('http://localhost:8080/clientes', cliente);
      alert('Cliente criado com sucesso!');
      setNome('');
      setEmail('');
      setTelefone('');
    } catch (error) {
      console.error('Erro ao criar cliente:', error);
      alert('Erro ao criar cliente!');
    }
  };

  return (
    <div className="cliente-management">
      <h2>Gestão de Clientes</h2>

      {/* Formulário de criação de cliente */}
      <div className="create-cliente-form">
        <h3>Criar Novo Cliente</h3>
        <form onSubmit={handleCreateCliente}>
          <input
            type="text"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            placeholder="Nome"
            required
          />
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Email"
            required
          />
          <input
            type="tel"
            value={telefone}
            onChange={(e) => setTelefone(e.target.value)}
            placeholder="Telefone"
            required
          />
          <button type="submit">Criar Cliente</button>
        </form>
      </div>
    </div>
  );
};

export default App;
